WITH filtered AS (SELECT *, CASE WHEN account_type IN ('LOAN', 'SAVINGS') THEN 'Tier 1' ELSE 'Other' END AS account_type_group FROM accounts WHERE opened_date >= TO_DATE('2023-03-03') AND account_type = 'LOAN'), kept_keys AS (SELECT id FROM filtered EXCEPT SELECT id FROM accounts WHERE MONTH(opened_date) IN (3, 7, 12)), verified AS (SELECT s.* FROM filtered s INNER JOIN kept_keys k ON s.id = k.id), not_flagged AS (SELECT s.* FROM verified s WHERE NOT EXISTS (SELECT 1 FROM transactions c WHERE c.account_id = s.id AND TO_DATE(c.txn_time) < '2024-06-01')), with_dims AS (SELECT s.*, p.email, p.segment, p.age FROM not_flagged s INNER JOIN customers p ON s.customer_id = p.id WHERE p.name LIKE 'D%') SELECT c.country, c.segment AS customer_segment, s.segment AS account_segment, COUNT(*) AS rows_total, SUM(s.age) AS total_age FROM with_dims s INNER JOIN customers c ON s.customer_id = c.id GROUP BY GROUPING SETS ((c.country, c.segment, s.segment), (c.country), ())
